mutations.from:
const frame = ambient.getStore();
if (frame === undefined) {
  throw new TransactionScopeError(
    TRANSACTION_NOT_OPEN,
    scope.transactionId,
    "a tenancy write must run inside UnitOfWork.run; no transaction is open",
  );
}

mutations.to:
const frame = ambient.getStore();
if (frame === undefined) {
  return client as unknown as TenancyTransactionClient;
}

mutations.from:
if (!open.has(scope.transactionId)) {
  throw new TransactionScopeError(
    TRANSACTION_SCOPE_UNKNOWN,
    scope.transactionId,
    `transaction ${scope.transactionId} is not open; it has already finished or never existed`,
  );
}

if (scope.transactionId !== frame.transactionId) {
  throw new TransactionScopeError(
    TRANSACTION_SCOPE_FOREIGN,
    scope.transactionId,
    `transaction ${scope.transactionId} is open but is not the one this write is running inside (${frame.transactionId})`,
  );
}

if (!isOrganizationRole(value)) {
  throw new UnreadableRowError(UNKNOWN_ORGANIZATION_ROLE, "OrganizationMembership.role", value);
}
return value;

if (!isProjectRole(value)) {
  throw new UnreadableRowError(UNKNOWN_PROJECT_ROLE, "ProjectMembership.role", value);
}
return value;

if (value !== PrincipalTier.OPERATOR && value !== PrincipalTier.END_USER) {
  throw new UnreadableRowError(UNKNOWN_PRINCIPAL_TIER, "EnvironmentSession.tier", value);
}
return value;

if (url.protocol !== "postgresql:" && url.protocol !== "postgres:") {
  throw new AdapterConfigurationError(
    DATABASE_URL_INVALID,
    `databaseUrl must use the postgresql scheme; received ${url.protocol}`,
  );
}

if (!Number.isInteger(value) || value <= 0) {
  throw new AdapterConfigurationError(
    POOL_SETTING_INVALID,
    `${label} must be a positive whole number; received ${String(value)}`,
  );
}
return value;

url.searchParams.set(
  "connection_limit",
  String(requirePositiveInteger("connectionLimit", pool.connectionLimit)),
);

export function isUniqueViolation(error: unknown): boolean {
  return errorCode(error) === UNIQUE_VIOLATION_CODE;
}

mutations.to:
export function isUniqueViolation(error: unknown): boolean {
  return String(error).includes("unique");
}

mutations.from:
const rows = await transactions
  .reader()
  .project.findMany({ where: { organizationId }, orderBy: [...LIST_ORDER] });
return rows.map(toProject);

mutations.to:
const identifiers = await transactions
  .reader()
  .project.findMany({ where: { organizationId }, orderBy: [...LIST_ORDER], select: { id: true } });
const rows = [];
for (const { id } of identifiers) {
  const row = await transactions.reader().project.findUnique({ where: { id } });
  if (row !== null) rows.push(row);
}
return rows.map(toProject);

mutations.from:
const serverOptions = buildServerOptions(pool);
if (serverOptions !== null) {
  const existing = url.searchParams.get("options");
  url.searchParams.set(
    "options",
    existing === null || existing.length === 0 ? serverOptions : `${existing} ${serverOptions}`,
  );
}

mutations.to:
for (const [setting, field] of SERVER_TIMEOUT_SETTINGS) {
  const value = pool[field];
  if (value !== undefined) {
    url.searchParams.set(setting, String(requirePositiveInteger(field, value)));
  }
}

